<?php $page_title='Community Groups'; require_once 'includes/header.php'; require_login(); if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['name']);$desc=trim($_POST['description']);if($name){$pdo->prepare('INSERT INTO community_groups(name,description,created_by) VALUES(?,?,?)')->execute([$name,$desc,user()['id']]);flash('success','Group created.');}redirect('groups.php');}$groups=$pdo->query('SELECT g.*,u.name creator FROM community_groups g LEFT JOIN users u ON u.id=g.created_by ORDER BY g.created_at DESC')->fetchAll(); ?>
<section class="page-hero"><span class="kicker">COMMUNITY / GROUPS</span><h1>Find your people.</h1><p>Create focused groups for volunteers, food drives, local neighborhoods and NGO coordination.</p></section><section class="admin-form-card"><h2>Create a group</h2><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label>Group name<input name="name" required placeholder="Faridabad Food Rescue"></label><label>Description<textarea name="description"></textarea></label><button class="btn primary">Create group</button></form></section><div class="feature-grid"><?php foreach($groups as $g):?><article class="feature-card"><div class="feature-icon">👥</div><h3><?=e($g['name'])?></h3><p><?=e($g['description']?:'Community coordination group.')?></p><small class="muted">Created by <?=e($g['creator']?:'FIBIN')?></small></article><?php endforeach;?></div>
